  builder_.add_RMS_ELEMENT_RESIDUAL(RMS_ELEMENT_RESIDUAL);
  builder_.add_MAX_ELEMENT_RESIDUAL(MAX_ELEMENT_RESIDUAL);
  builder_.add_EPOCH_HALF_SPAN(EPOCH_HALF_SPAN);
